package ociresources

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Form fields, in the order they are rendered. Kind comes first because it is
// what decides whether the two group-only fields exist at all.
const (
	regFieldKind = iota
	regFieldURL
	regFieldSlug
	regFieldAlias
	regFieldUsername
	regFieldPassword
	regFieldAuth
	regFieldMgmtURL  // group only
	regFieldProvider // group only
	regFieldSubmit
)

const registryFormMaxField = regFieldSubmit

// RegistryFormSubmitMsg is sent when the registry form is submitted
type RegistryFormSubmitMsg struct {
	Index    int // -1 for new, >= 0 for edit
	Item     config.RegistryItem
	Password string // not stored in config; used for docker login
}

// RegistryFormCancelMsg is sent when the registry form is cancelled
type RegistryFormCancelMsg struct{}

// RegistryForm is a form for adding or editing a registry entry
type RegistryForm struct {
	index         int // -1 = new, >=0 = edit
	width         int
	urlInput      textinput.Model
	slugInput     textinput.Model
	usernameInput textinput.Model
	passwordInput textinput.Model
	aliasInput    textinput.Model
	nexusURLInput textinput.Model
	authModeIdx   int
	kindIdx       int
	providerIdx   int
	// parent is carried through untouched: membership is decided by discovery,
	// not by this form, but what an entry may say about credentials depends on
	// it — and dropping it would orphan the entry from its group.
	parent string
	// existing is every configured entry, so that a slug already in use can be
	// refused here rather than at the next load (§3.8, decision 1).
	existing     []config.RegistryItem
	focusedField int
	err          string
}

// NewRegistryForm creates a form for adding a new registry
func NewRegistryForm(existing []config.RegistryItem, width int) *RegistryForm {
	return newRegistryForm(-1, config.RegistryItem{AuthMode: config.AuthCredentials}, existing, width)
}

// NewRegistryEditForm creates a form for editing an existing registry
func NewRegistryEditForm(index int, item config.RegistryItem, existing []config.RegistryItem, width int) *RegistryForm {
	return newRegistryForm(index, item, existing, width)
}

func newRegistryForm(index int, item config.RegistryItem, existing []config.RegistryItem, width int) *RegistryForm {
	urlInput := textinput.New()
	urlInput.CharLimit = 256
	urlInput.Placeholder = "registry.example.com"
	theme.StyleTextInput(&urlInput)
	urlInput.SetValue(item.URL)
	urlInput.Focus()

	slugInput := textinput.New()
	slugInput.CharLimit = 64
	slugInput.Placeholder = "derived from the alias or the host  (optional)"
	theme.StyleTextInput(&slugInput)
	slugInput.SetValue(item.Slug)

	usernameInput := textinput.New()
	usernameInput.CharLimit = 128
	usernameInput.Placeholder = "username"
	theme.StyleTextInput(&usernameInput)
	usernameInput.SetValue(item.Username)

	passwordInput := textinput.New()
	passwordInput.CharLimit = 256
	passwordInput.Placeholder = "password"
	passwordInput.EchoMode = textinput.EchoPassword
	passwordInput.EchoCharacter = '•'
	theme.StyleTextInput(&passwordInput)

	aliasInput := textinput.New()
	aliasInput.CharLimit = 32
	aliasInput.Placeholder = "gl"
	theme.StyleTextInput(&aliasInput)
	aliasInput.SetValue(item.Alias)

	nexusURLInput := textinput.New()
	nexusURLInput.CharLimit = 512
	nexusURLInput.Placeholder = "https://registry-mgr.example.com/path/to/group  (optional)"
	theme.StyleTextInput(&nexusURLInput)
	nexusURLInput.SetValue(item.ManagementURL)

	f := &RegistryForm{
		index:         index,
		width:         width,
		urlInput:      urlInput,
		slugInput:     slugInput,
		usernameInput: usernameInput,
		passwordInput: passwordInput,
		aliasInput:    aliasInput,
		nexusURLInput: nexusURLInput,
		authModeIdx:   indexOf(config.AuthModes(item.Parent != ""), item.AuthMode),
		kindIdx:       indexOf(config.Kinds(), item.Kind),
		providerIdx:   indexOf(config.Providers(), item.Provider),
		parent:        item.Parent,
		existing:      existing,
		focusedField:  regFieldURL,
	}
	f.resizeInputs()
	return f
}

// indexOf returns the position of value in options, or 0 when it is absent —
// an unset kind is a plain registry and an unset provider is generic, and both
// are first in their list.
func indexOf(options []string, value string) int {
	for i, o := range options {
		if o == value {
			return i
		}
	}
	return 0
}

// SetWidth updates the form width and resizes inputs accordingly.
func (f *RegistryForm) SetWidth(w int) {
	f.width = w
	f.resizeInputs()
}

func (f *RegistryForm) resizeInputs() {
	// Label overhead: viewport border (2) + indent (2) + longest label
	// "Management URL " + chevron + spaces (~18)
	const labelOverhead = 20
	w := max(f.width-labelOverhead, 20)
	f.urlInput.Width = w
	f.slugInput.Width = w
	f.usernameInput.Width = w
	f.passwordInput.Width = w
	f.aliasInput.Width = w
	f.nexusURLInput.Width = w
}

// isGroup reports whether the entry being edited is a repository-manager group.
func (f *RegistryForm) isGroup() bool {
	return config.Kinds()[f.kindIdx] == config.KindGroup
}

// isFieldSkipped reports whether a field is absent for the current kind. The
// management URL and the provider describe where a group's members come from,
// so they mean nothing on a plain registry.
func (f *RegistryForm) isFieldSkipped(idx int) bool {
	return !f.isGroup() && (idx == regFieldMgmtURL || idx == regFieldProvider)
}

func (f *RegistryForm) nextField() int {
	next := (f.focusedField + 1) % (registryFormMaxField + 1)
	for f.isFieldSkipped(next) {
		next = (next + 1) % (registryFormMaxField + 1)
	}
	return next
}

func (f *RegistryForm) prevField() int {
	prev := (f.focusedField - 1 + registryFormMaxField + 1) % (registryFormMaxField + 1)
	for f.isFieldSkipped(prev) {
		prev = (prev - 1 + registryFormMaxField + 1) % (registryFormMaxField + 1)
	}
	return prev
}

// GetTitle returns the form title for the viewport breadcrumb
func (f *RegistryForm) GetTitle() string {
	if f.index < 0 {
		return "New Registry"
	}
	return "Edit Registry"
}

// Update handles messages for the registry form
func (f *RegistryForm) Update(msg tea.Msg) (*RegistryForm, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		return f.handleKeyMsg(msg)
	}
	return f.updateActiveInput(msg)
}

func (f *RegistryForm) handleKeyMsg(msg tea.KeyMsg) (*RegistryForm, tea.Cmd) {
	switch msg.String() {
	case "esc":
		return f, func() tea.Msg { return RegistryFormCancelMsg{} }
	case "down":
		f.focusedField = f.nextField()
		f.updateFocus()
		return f, nil
	case "up":
		f.focusedField = f.prevField()
		f.updateFocus()
		return f, nil
	case "left":
		return f.cycle(-1)
	case "right":
		return f.cycle(1)
	case "enter":
		if f.focusedField == regFieldSubmit {
			return f.submit()
		}
		f.focusedField = f.nextField()
		f.updateFocus()
		return f, nil
	}
	return f.updateActiveInput(msg)
}

// cycle moves a closed-list field by one step (Rule 132).
func (f *RegistryForm) cycle(step int) (*RegistryForm, tea.Cmd) {
	switch f.focusedField {
	case regFieldKind:
		f.kindIdx = wrap(f.kindIdx+step, len(config.Kinds()))
		// Leaving a group blurs the fields that just disappeared.
		f.updateFocus()
	case regFieldProvider:
		f.providerIdx = wrap(f.providerIdx+step, len(config.Providers()))
	case regFieldAuth:
		f.authModeIdx = wrap(f.authModeIdx+step, len(f.authModes()))
	}
	return f, nil
}

// authModes returns the modes this entry may take.
func (f *RegistryForm) authModes() []string {
	return config.AuthModes(f.parent != "")
}

// wrap returns i modulo n, for negative i as well.
func wrap(i, n int) int {
	return (i%n + n) % n
}

func (f *RegistryForm) updateFocus() {
	f.urlInput.Blur()
	f.slugInput.Blur()
	f.usernameInput.Blur()
	f.passwordInput.Blur()
	f.aliasInput.Blur()
	f.nexusURLInput.Blur()
	switch f.focusedField {
	case regFieldURL:
		f.urlInput.Focus()
	case regFieldSlug:
		f.slugInput.Focus()
	case regFieldAlias:
		f.aliasInput.Focus()
	case regFieldUsername:
		f.usernameInput.Focus()
	case regFieldPassword:
		f.passwordInput.Focus()
	case regFieldMgmtURL:
		f.nexusURLInput.Focus()
	}
}

func (f *RegistryForm) updateActiveInput(msg tea.Msg) (*RegistryForm, tea.Cmd) {
	var cmd tea.Cmd
	switch f.focusedField {
	case regFieldURL:
		f.urlInput, cmd = f.urlInput.Update(msg)
	case regFieldSlug:
		f.slugInput, cmd = f.slugInput.Update(msg)
	case regFieldAlias:
		f.aliasInput, cmd = f.aliasInput.Update(msg)
	case regFieldUsername:
		f.usernameInput, cmd = f.usernameInput.Update(msg)
	case regFieldPassword:
		f.passwordInput, cmd = f.passwordInput.Update(msg)
	case regFieldMgmtURL:
		f.nexusURLInput, cmd = f.nexusURLInput.Update(msg)
	}
	return f, cmd
}

func (f *RegistryForm) submit() (*RegistryForm, tea.Cmd) {
	url := strings.TrimSpace(f.urlInput.Value())
	if url == "" {
		f.err = "URL is required"
		return f, nil
	}

	item := config.RegistryItem{
		Kind:     config.Kinds()[f.kindIdx],
		Parent:   f.parent,
		URL:      url,
		Username: strings.TrimSpace(f.usernameInput.Value()),
		Alias:    strings.TrimSpace(f.aliasInput.Value()),
		AuthMode: f.authModes()[f.authModeIdx],
	}
	if f.isGroup() {
		item.Provider = config.Providers()[f.providerIdx]
		item.ManagementURL = strings.TrimSpace(f.nexusURLInput.Value())
	}

	slug, err := f.resolveSlug(item)
	if err != nil {
		f.err = err.Error()
		return f, nil
	}
	item.Slug = slug

	pass := f.passwordInput.Value()
	idx := f.index
	return f, func() tea.Msg {
		return RegistryFormSubmitMsg{Index: idx, Item: item, Password: pass}
	}
}

// resolveSlug settles the entry's slug: what was typed, if it is a slug and not
// already taken, or the one derived from the alias or the host. A typed value is
// refused rather than corrected — a slug is a link target, and quietly changing
// it is how a group loses its members.
func (f *RegistryForm) resolveSlug(item config.RegistryItem) (string, error) {
	typed := strings.TrimSpace(f.slugInput.Value())
	if typed == "" {
		return f.freeSlug(config.ProposeSlug(item)), nil
	}
	if config.Slugify(typed) != typed {
		return "", fmt.Errorf("slug %q: use lowercase letters, digits and dashes", typed)
	}
	if f.slugTaken(typed) {
		return "", fmt.Errorf("slug %q is already used by another registry", typed)
	}
	return typed, nil
}

// freeSlug returns base, or base-2, base-3… until one is not in use.
func (f *RegistryForm) freeSlug(base string) string {
	slug := base
	for n := 2; f.slugTaken(slug); n++ {
		slug = fmt.Sprintf("%s-%d", base, n)
	}
	return slug
}

// slugTaken reports whether another entry — not the one being edited — holds it.
func (f *RegistryForm) slugTaken(slug string) bool {
	for i, existing := range f.existing {
		if i != f.index && existing.Slug == slug {
			return true
		}
	}
	return false
}

// View renders the registry form (Rule 131: starts with empty line)
func (f *RegistryForm) View() string {
	var b strings.Builder

	b.WriteString(theme.EmptyLineBg(f.width) + "\n")

	if f.err != "" {
		b.WriteString(theme.StatusErrorStyle.Render("  " + f.err))
		b.WriteString("\n\n")
	}

	b.WriteString(f.renderCycleField("Kind", config.Kinds()[f.kindIdx], regFieldKind))
	b.WriteString("\n\n")
	b.WriteString(f.renderField("URL", f.urlInput.View(), regFieldURL))
	b.WriteString("\n\n")
	b.WriteString(f.renderField("Slug", f.slugInput.View(), regFieldSlug))
	b.WriteString("\n\n")
	b.WriteString(f.renderField("Alias", f.aliasInput.View(), regFieldAlias))
	b.WriteString("\n\n")
	b.WriteString(f.renderField("Username", f.usernameInput.View(), regFieldUsername))
	b.WriteString("\n\n")
	b.WriteString(f.renderField("Password", f.passwordInput.View(), regFieldPassword))
	b.WriteString("\n\n")
	b.WriteString(f.renderCycleField("Auth", f.authModes()[f.authModeIdx], regFieldAuth))
	b.WriteString("\n\n")
	if f.isGroup() {
		b.WriteString(f.renderField("Management URL", f.nexusURLInput.View(), regFieldMgmtURL))
		b.WriteString("\n\n")
		b.WriteString(f.renderCycleField("Provider", config.Providers()[f.providerIdx], regFieldProvider))
		b.WriteString("\n\n")
	}
	b.WriteString("  ")
	b.WriteString(theme.RenderButton("Save", f.focusedField == regFieldSubmit, "primary"))

	return b.String()
}

func (f *RegistryForm) renderField(label, value string, fieldIdx int) string {
	var labelStr string
	if f.focusedField == fieldIdx {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
	}
	return labelStr + "\n  " + value
}

// renderCycleField renders a closed-list field (Rule 132).
func (f *RegistryForm) renderCycleField(label, value string, fieldIdx int) string {
	selectLabel := label + " " + theme.IconSelect + " "
	if f.focusedField == fieldIdx {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+selectLabel+theme.IconChevronRight+" ") + theme.Bg(value)
	}
	return theme.Bg("  "+selectLabel+theme.IconChevronRight+" ") + theme.Bg(value)
}

package ociresources

import (
	"fmt"
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// getSelectedRegistry returns a pointer to the selected registry item, or nil —
// including inside a group, where the rows are cached members rather than
// config entries and nothing on them is editable.
func (m Model) getSelectedRegistry() *config.RegistryItem {
	idx := m.getSelectedRegistryIndex()
	if idx < 0 {
		return nil
	}
	return &m.registries[idx]
}

// enterSelectedGroup drills into the selected group (Rule 111: → goes down a
// level). A group with nothing discovered has no level to enter.
func (m Model) enterSelectedGroup() (tea.Model, tea.Cmd) {
	reg := m.getSelectedRegistry()
	if reg == nil || reg.Kind != config.KindGroup {
		return m, nil
	}
	if len(m.groupCache[reg.Slug].Members) == 0 {
		return m, m.footer.Warn("No members discovered yet — press ctrl+r to look")
	}
	m.registryGroupSlug = reg.Slug
	m.updateRegistryTable()
	m.registryTable.GotoTop()
	return m, nil
}

// leaveGroup goes back up to the registry list (Rule 111: ← and esc).
func (m Model) leaveGroup() (tea.Model, tea.Cmd) {
	if m.registryGroupSlug == "" {
		return m, nil
	}
	m.registryGroupSlug = ""
	m.updateRegistryTable()
	m.registryTable.GotoTop()
	return m, nil
}

// getSelectedRegistryIndex returns the index of the selected registry, or -1 —
// including inside a group, where the rows are cached members and carry no
// config index of their own.
func (m Model) getSelectedRegistryIndex() int {
	row, ok := m.registryTable.Selected()
	if !ok || row.config < 0 || row.config >= len(m.registries) {
		return -1
	}
	return row.config
}

// editSelectedRegistry opens a registry edit form for the selected entry
func (m Model) editSelectedRegistry() (tea.Model, tea.Cmd) {
	idx := m.getSelectedRegistryIndex()
	if idx < 0 {
		return m, nil
	}
	m.registryForm = NewRegistryEditForm(idx, m.registries[idx], m.registries, m.width-2)
	return m, nil
}

// loginSelectedRegistry triggers a docker login for the selected registry
// loginSelectedRegistry opens the edit form so the user can enter a password.
// Passwords are never stored in config, so login always requires re-entry.
// toggleSelectedRegistryAuth logs in or out depending on where the row stands.
//
// The row already answers "am I logged in" — it is the Logged column, and the
// cell the spinner takes while the operation runs. Two keys separated by shift
// alone made the user answer a question the screen had already answered, and
// pressing the wrong one silently did the opposite of what was wanted.
func (m Model) toggleSelectedRegistryAuth() (tea.Model, tea.Cmd) {
	reg := m.getSelectedRegistry()
	if reg == nil {
		return m, nil
	}
	if m.registryLoginStatus[reg.URL] {
		return m.logoutSelectedRegistry()
	}
	return m.loginSelectedRegistry()
}

func (m Model) loginSelectedRegistry() (tea.Model, tea.Cmd) {
	idx := m.getSelectedRegistryIndex()
	if idx < 0 {
		return m, nil
	}
	reg := m.registries[idx]
	if !config.UsesCredentials(reg.AuthMode) {
		return m, m.footer.Warn("This registry is marked anonymous")
	}
	m.registryForm = NewRegistryEditForm(idx, reg, m.registries, m.width-2)
	return m, nil
}

// refreshRegistries reloads the registry list and login status, and re-runs
// discovery for the selected group.
//
// Discovery is explicit rather than automatic (§3.8, decision 3): it costs a
// network round trip against a repository manager, and running it on every
// browser open is what made the browser wait. The Members column is what says
// how old the answer it replaces was.
func (m Model) refreshRegistries() (tea.Model, tea.Cmd) {
	m.registries = m.config.Registry.Registries

	cmds := []tea.Cmd{m.registryLoginStatusCmd()}
	if cmd := m.refreshSelectedGroupCmd(); cmd != nil {
		cmds = append(cmds, cmd, m.spinner.Tick)
	}
	m.updateRegistryTable()
	return m, tea.Batch(cmds...)
}

// refreshSelectedGroupCmd starts a discovery for the selected row when it is a
// group that is not already being refreshed. Returns nil otherwise, which is
// the ordinary case: a plain registry has no members to discover.
func (m *Model) refreshSelectedGroupCmd() tea.Cmd {
	reg := m.getSelectedRegistry()
	if reg == nil || reg.Kind != config.KindGroup || m.refreshingGroups[reg.Slug] {
		return nil
	}
	m.refreshingGroups[reg.Slug] = true
	return detectRegistryGroupCmd(*reg, "")
}

// deleteSelectedRegistry shows a confirm modal for registry removal
func (m Model) deleteSelectedRegistry() (tea.Model, tea.Cmd) {
	reg := m.getSelectedRegistry()
	if reg == nil {
		return m, nil
	}
	m.pendingAction = "delete-registry"
	m.confirmModal = sharedcomponents.NewConfirmModal("Remove Registry", fmt.Sprintf("Remove registry '%s'?", reg.URL))
	return m, nil
}

// handleRegistryFormSubmit saves a new or edited registry to the config and optionally logs in.
func (m Model) handleRegistryFormSubmit(msg RegistryFormSubmitMsg) (tea.Model, tea.Cmd) {
	m.registryForm = nil
	if msg.Index < 0 {
		m.config.Registry.Registries = append(m.config.Registry.Registries, msg.Item)
	} else if msg.Index < len(m.config.Registry.Registries) {
		m.config.Registry.Registries[msg.Index] = msg.Item
	}
	m.registries = m.config.Registry.Registries
	m.updateRegistryTable()
	if err := config.Save(m.config); err != nil {
		log.Printf("ERROR [oci_resources] save registry config: %v", err)
		return m, m.footer.Error("Failed to save registry — check logs")
	}
	m.footer.Clear()
	if msg.Password != "" && config.UsesCredentials(msg.Item.AuthMode) {
		m.registryTable.MarkBusy(msg.Item.URL, "Logging in to "+browserAlias(msg.Item))
		return m, tea.Batch(registryLoginCmd(msg.Item.URL, msg.Item.Username, msg.Password), m.busyTick())
	}
	return m, nil
}

// handleRegistryLoginComplete processes the result of a docker login operation.
// registryLoginStatusCmd builds a command that checks login status for all configured registries.
func (m Model) registryLoginStatusCmd() tea.Cmd {
	urls := make([]string, 0, len(m.registries))
	for _, reg := range m.registries {
		if config.UsesCredentials(reg.AuthMode) {
			urls = append(urls, reg.URL)
		}
	}
	return checkRegistryLoginStatusCmd(urls)
}

func (m Model) handleRegistryLoginComplete(msg RegistryLoginCompleteMsg) (tea.Model, tea.Cmd) {
	m.registryTable.ClearBusy(msg.RegistryURL)
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] login %s: %v", msg.RegistryURL, msg.Err)
		m.registryLoginStatus[msg.RegistryURL] = false
		m.updateRegistryTable()
		return m, m.footer.Error("Login failed — check logs")
	}
	log.Printf("INFO [oci_resources] login successful: %s", msg.RegistryURL)
	m.footer.Clear()
	// Optimistic update + re-check from disk to confirm credential helper cases
	m.registryLoginStatus[msg.RegistryURL] = true
	m.updateRegistryTable()
	return m, m.registryLoginStatusCmd()
}

// logoutSelectedRegistry triggers a docker logout for the selected registry
func (m Model) logoutSelectedRegistry() (tea.Model, tea.Cmd) {
	reg := m.getSelectedRegistry()
	if reg == nil {
		return m, nil
	}
	if m.registryTable.IsBusy(reg.URL) {
		return m, m.footer.Warn(busyMessage)
	}
	m.registryTable.MarkBusy(reg.URL, "Logging out of "+browserAlias(*reg))
	return m, tea.Batch(registryLogoutCmd(reg.URL), m.busyTick())
}

func (m Model) handleRegistryLogoutComplete(msg RegistryLogoutCompleteMsg) (tea.Model, tea.Cmd) {
	m.registryTable.ClearBusy(msg.RegistryURL)
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] logout %s: %v", msg.RegistryURL, msg.Err)
		return m, m.footer.Error("Logout failed — check logs")
	}
	log.Printf("INFO [oci_resources] logout successful: %s", msg.RegistryURL)
	m.footer.Clear()
	// Do NOT call registryLoginStatusCmd here: docker logout docker.io may not remove
	// the https://index.docker.io/v1/ key from config.json, causing the file-check to
	// override this correct false status back to true.
	m.registryLoginStatus[msg.RegistryURL] = false
	m.updateRegistryTable()
	return m, nil
}

